   elsif ( $self->{store}->sync_due() ) {
     dbg("bayes: opportunistic call found journal sync due");

     # sync will bring the DB R/W as necessary, may untie as well
-    $self->sync(1,0);
+    $self->{main}->{bayes_scanner}->sync(1,0);

